// This is used by /randomBytes

export function assertSize(size) {
  if (!(Number.isSafeInteger(size) && size > 0)) throw new TypeError('Invalid size')
}

const TypedArray = Object.getPrototypeOf(Uint8Array)
if (TypedArray.name !== 'TypedArray') throw new Error('Bad TypedArray?')

const basic = [Int8Array, Int16Array, Int32Array, Uint8Array, Uint16Array, Uint32Array]
const optional = [globalThis.Uint8ClampedArray, globalThis.BigInt64Array, globalThis.BigUint64Array]
const allowed = [...basic, ...optional].filter(Boolean)

export function assertRandomTarget(target) {
  if (target instanceof TypedArray && allowed.some((t) => target instanceof t)) return
  throw new TypeError('The data argument must be an integer-type TypedArray')
}
